// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 guessHash, address actor) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 1 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // target block is b+1, so by block b+2 settle() must succeed
        vm.roll(block.number + 2);

        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
